#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_gather.h"
#include <torch/extension.h>
#include <torch/library.h>

namespace ascend_kernel {

constexpr int64_t MAX_CORES = 40;

at::Tensor gather(const at::Tensor& self, int64_t dim, const at::Tensor& index, bool sparse_grad) {
    // ---- Input validation ----
    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
                "gather: input must be on NPU device");
    TORCH_CHECK(index.device().type() == at::DeviceType::PrivateUse1,
                "gather: index must be on NPU device");

    int64_t ndim = self.dim();
    if (dim < 0) dim += ndim;

    TORCH_CHECK(dim >= 0 && dim < ndim,
                "gather: dim out of range, got dim=", dim);
    TORCH_CHECK(index.dim() == ndim,
                "gather: index must have same ndim as input");

    TORCH_CHECK(self.scalar_type() == at::kFloat ||
                self.scalar_type() == at::kHalf ||
                self.scalar_type() == at::kBFloat16,
                "gather: only float32, float16 and bfloat16 are supported");

    // ---- Contiguous ----
    at::Tensor inputContiguous = self.contiguous();
    at::Tensor indexContiguous = index.contiguous();

    // ---- Dimension params ----
    int64_t N = inputContiguous.size(dim);
    int64_t K = indexContiguous.size(dim);
    int64_t dtypeSize = inputContiguous.element_size();

    // ---- Index to int32 ----
    auto indexInt32 = indexContiguous.to(at::kInt);

    // ---- Build permute dims: move dim to last ----
    std::vector<int64_t> permuteDims;
    for (int64_t i = 0; i < ndim; i++) {
        if (i != dim) permuteDims.push_back(i);
    }
    permuteDims.push_back(dim);

    // ---- Permute and flatten to 2D [totalRows, K/N] ----
    auto inputPermuted = inputContiguous.permute(permuteDims).contiguous();
    auto indexPermuted = indexInt32.permute(permuteDims).contiguous();

    int64_t totalRowsIn = inputPermuted.numel() / N;
    int64_t totalRowsIdx = indexPermuted.numel() / K;

    auto inputFlat = inputPermuted.reshape({totalRowsIn, N});
    auto indexFlat = indexPermuted.reshape({totalRowsIdx, K});

    auto outputFlat = at::empty({totalRowsIdx, K},
        inputContiguous.options().dtype(
            inputContiguous.scalar_type() == at::kBFloat16
                ? at::kBFloat16 : inputContiguous.scalar_type()));

    // ---- Batch launch ----
    int64_t totalRows = totalRowsIdx;
    int64_t rowOffset = 0;
    uint32_t blockDim = static_cast<uint32_t>(std::min(totalRows, MAX_CORES));
    if (blockDim < 1) blockDim = 1;

    int64_t inputRows = totalRowsIn;
    int64_t srcDimSize = N;
    int64_t indexSize = K;

    EXEC_KERNEL_CMD(gather, blockDim, inputFlat, indexFlat, outputFlat,
                    inputRows, srcDimSize, indexSize, dtypeSize, totalRows, rowOffset);

    // ---- Reshape back ----
    // outputFlat is [totalRowsIdx, K], reshape to permuted shape, then permute back
    auto outputPermuted = outputFlat.reshape(indexPermuted.sizes());

    // Build inverse permute dims
    std::vector<int64_t> invPermute(ndim);
    for (int64_t i = 0; i < ndim - 1; i++) {
        invPermute[permuteDims[i]] = i;
    }
    invPermute[dim] = ndim - 1;

    auto outputResult = outputPermuted.permute(invPermute).contiguous();

    return outputResult;
}

}  // namespace ascend_kernel
